function 判断_抗魔值()
	setDict(0 , "抗魔值.txt")
	useDict(0)
	local 最大值 = nil
	for i = 1 , 5 do
		local str = ocr(209 , 624 , 353 , 655 , "ffc200-303030|c59a00-303030" , 0.85 , 1 , 1)
		local str1 = ocr(209 , 624 , 353 , 655 , "ffc200-303030|c59a00-303030" , 0.85 , 10 , 10)
		local val = tonumber(str)
		local val1 = tonumber(str1)
		if val ~= nil and (最大值 == nil or val > 最大值) then
			最大值 = val
		end
		if val1 ~= nil and (最大值 == nil or val1 > 最大值) then
			最大值 = val1
		end
		sleep(100)
	end
	if 最大值 ~= nil then
		显示('当前角色抗魔值:' .. 最大值)
	end
	return 最大值
end

