--[[
功能: 判断是否为"能源中心选择地下城"界面。
逻辑:
- 最多循环5次来确认界面。
- 每次循环会寻找两种不同的界面特征。
- 如果任何一个特征累计找到3次，就确认是该界面，函数返回 true。
- 特殊情况：如果第一次循环时，两种特征都找不到，那么就认为不是该界面，函数直接返回 false，不再继续尝试。
]]
function 判断_能源中心选择地下城界面()
	
	local x , y = findMultiColor(53 , 11 , 170 , 42 , "fff3bd-202020" , "14|-2|b5aa84-202020|29|5|fff3bd-202020|40|14|fff3bd-202020|55|3|fff3bd-202020|52|6|b5a684-202020|-28|5|ffefb5-202020|-29|15|ada27b-202020|-23|6|ffefb5-202020|-15|1|fff3bd-202020|-18|0|fff3bd-202020|-51|3|fff3bd-202020|-33|13|fff3bd-202020|-42|7|ffefb5-202020|-38|3|ffefb5-202020|17|3|000010-202020|-9|5|000010-202020" , 0 , 0.9)
	-- 寻找特征2()
	local x1 , y1 = findMultiColor(406 , 310 , 492 , 327 , "ffffff-202020" , "36|4|ffffff-202020|38|7|ffffff-202020|42|-5|ffffff-202020|16|2|ffffff-202020|25|-2|ffffff-202020|16|-5|c5cac5-202020|-3|6|fffbff-202020|-2|4|ffffff-202020|9|6|ffffff-202020|11|-4|ffffff-202020|-36|7|fffbff-202020|-35|6|ffffff-202020|-26|-3|ffffff-202020|-25|-2|ffffff-202020|7|-2|210829-202020" , 0 , 0.9)
	
	if not 判断_普鲁兹发电站选择难度界面() then
		-- 如果找到了特征1，增加其计数
		if x ~= - 1 then
			
			显示('选择地下城界面')
			随机延时(800 , 1000)
			return true
			
		end
		
		-- 如果找到了特征2，增加其计数
		if x1 ~= - 1 then
			
			显示('选择地下城界面2')
			随机延时(800 , 1000)
			return true
			
		end
	end
	
	return false
end
