function 判断_返回城镇()
	
	if 判断_翻牌界面() or 清屏_任务跳过() then
		print('返回城镇界面检测到,确认,任务跳过')
		
	elseif 判断_技能加点界面() then
		功能_技能加点配置()
		
	end
	
	if 判断_返回城镇1() then
		
		显示('返回城镇界面')
		
		if 判断_装备修理() then
			print('检查到装备需要修理')
			for i = 1 , 20 do
				显示('检测到修理装备处理中')
				随机延时(500 , 800)
				if 判断_修理装备界面() then
					按下点击({1000 , 607 , 1163 , 651})--修理
					随机延时(1000 , 2000)
					清屏(true)
					
				elseif 判断_装备修理() then
					随机延时(1000 , 2000)
				elseif 判断_副本中() then
					break
				else
					break
				end
			end
			
		end
		
		if 判断_背包满了() then
			功能_检测背包_返回城镇界面()
			return false
		else
			return true
		end
		
	end
	return false
end

