识别泰拉数量时间 = 0
识别抗魔值时间 = 0
function 判断_打开背包界面()
	setDict(0 , "界面判断.txt")
	useDict(0)
	local ret , x , y = findStr(54 , 14 , 101 , 40 , "背包" , "ffefb5-303030" , 0.85 , 10 , 10)
	if x ~= - 1 and y ~= - 1 then
		if os.time() - 识别泰拉数量时间 > 120 then
			local 新泰拉数量 = 判断_泰拉数量()
			
			if 新泰拉数量 then
				
				当前泰拉数量 = 新泰拉数量
				print('当前泰拉数量已保存到全局变量: ' .. 当前泰拉数量)
				识别泰拉数量时间 = os.time()
			else
				print('泰拉数量识别失败，保留上次数量: ' .. (当前泰拉数量 or '无'))
				识别泰拉数量时间 = 0
				--当前泰拉数量 = nil
			end
			
		end
		
		if os.time() - 识别抗魔值时间 > 120 then
			if 判断_选中道具() then
				local 新抗魔值 = 判断_抗魔值()
				if 新抗魔值 then
					
					if 当前角色抗魔值 == nil or 新抗魔值 > 当前角色抗魔值 then
						当前角色抗魔值 = 新抗魔值
						print('当前抗魔值已更新到全局变量: ' .. 当前角色抗魔值)
					else
						print('当前抗魔值保留全局更大值: ' .. 当前角色抗魔值)
					end
					识别抗魔值时间 = os.time()
					
				else
					print('抗魔值识别失败，保留上次数量: ' .. (当前角色抗魔值 or '无'))
					识别抗魔值时间 = 0
					--当前角色抗魔值 = nil
				end
			end
			
		end
		
		return true
	end
	if 入口_自动装备_自动穿装备() then
		随机延时(400 , 500)
	end
	return false
end
