	if x ~= - 1 and y ~= - 1 then
		
		if os.time() - 识别泰拉数量时间 > 60 then
			local 新泰拉数量 = 判断_泰拉数量()
			if 新泰拉数量 then
				
				当前泰拉数量 = 新泰拉数量
				print('当前泰拉数量已保存到全局变量: ' .. 当前泰拉数量)
				识别泰拉数量时间 = os.time()
			else
				print('泰拉数量识别失败，保留上次数量: ' .. (当前泰拉数量 or '无'))
				识别泰拉数量时间 = 0
				当前泰拉数量 = nil
			end
		end
		return true
	end
	return false
end

