function 功能_输入自定义内容(内容)
	
	setStopCallBack(function(error)
		imeLib.unlock()
	end)
	
	imeLib.lock()
	
	-- 调用输入函数并返回结果
	local 结果 = imeLib.setText(内容)
	
	if 结果 then
		print("随机昵称输入成功: " .. 内容)
		return true
	else
		print("随机昵称输入失败: " .. 内容)
		return false
	end
	
end

