			return true
		end
		
		local x1 , y1 = findMultiColor(1195 , 81 , 1264 , 116 , "decea4-303030" , "-8|12|b59e84-303030|-8|3|b5aa84-303030|-10|-6|f7ebbd-303030|-10|-5|efe3b5-303030|-5|-3|d6caa4-303030|39|-7|f7ebbd-303030|27|-7|f7ebb5-303030|-3|7|c5b28c-303030|-4|8|c5ae8c-303030|0|7|c5b28c-303030|3|6|c5b28c-303030|16|8|c5ae8c-303030|14|6|ceb694-303030|10|-3|e6dbad-303030" , 0 , 0.9)
		if x1 ~= - 1 and y1 ~= - 1 then
			显示('是洛兰地图2')
			
			return true
		end
		
		随机延时(100 , 150)
	end
	
	显示('不是洛兰地图')
	return false
end

