function 查找并点击所有匹配(模板 , 点击延时 , 点击范围)
	-- 默认值设置
	点击延时 = 点击延时 or {500 , 800}
	-- 点击范围为nil表示精确点击
	
	local 匹配列表 = findMultiColorAllT(模板)
	
	if 匹配列表 == nil or #匹配列表 == 0 then
		print("未找到任何匹配项")
		return false
	end
	
	--显示("找到 " .. #匹配列表 .. " 个匹配项，开始依次点击")
	for i , 坐标 in ipairs(匹配列表) do
		if 坐标.x ~= nil and 坐标.y ~= nil then
			if 点击范围 then
				-- 在找到的坐标周围的矩形区域内点击
				local x1 = 坐标.x + 点击范围[1]
				local y1 = 坐标.y + 点击范围[2]
				local x2 = 坐标.x + 点击范围[3]
				local y2 = 坐标.y + 点击范围[4]
				
				--显示("点击范围: [" .. x1 .. "," .. y1 .. "," .. x2 .. "," .. y2 .. "]")
				按下点击({x1 , y1 , x2 , y2} , {100 , 200})
				
			else
				-- 精确点击找到的坐标
				--显示("精确点击: x=" .. 坐标.x .. ", y=" .. 坐标.y)
				按下点击(坐标.x , 坐标.y)
			end
			
			随机延时(点击延时[1] , 点击延时[2])
		end
	end
	return true
end

