			local 新泰拉数量 = 判断_泰拉数量()
			if 新泰拉数量 then
				
				当前泰拉数量 = 新泰拉数量
				print('当前泰拉数量已保存到全局变量: ' .. 当前泰拉数量)
				识别泰拉数量时间 = os.time()
