function 判断_遍历仓库格子_金色小晶块()
	
	-- 定义格子位置：每4个数字表示一个格子的 x1, y1, x2, y2
	local 格子位置 = {
		{189 , 136 , 257 , 206} , -- 格子1
		{274 , 136 , 343 , 206} , -- 格子2
		{360 , 137 , 430 , 205} , -- 格子3
		{449 , 137 , 516 , 205} , -- 格子4
		{531 , 138 , 602 , 206} , -- 格子5
		{190 , 222 , 259 , 292} , -- 格子6
		{275 , 223 , 342 , 290} , -- 格子7
		{363 , 224 , 427 , 291} , -- 格子8
		{449 , 223 , 514 , 291} , -- 格子9
		{535 , 224 , 599 , 290} , -- 格子10
		{190 , 310 , 256 , 376} , -- 格子11
		{275 , 222 , 344 , 289} , -- 格子12
		{275 , 309 , 342 , 375} , -- 格子13
		{450 , 309 , 512 , 377} , -- 格子14
		{533 , 311 , 597 , 376} , -- 格子15
		
	}
	
	-- 物品识别函数：金色小金块
	local function 检测_金色小金块(x1 , y1 , x2 , y2)
		local x , y = findMultiColor(x1 , y1 , x2 , y2 , "c58e42-202020" , "-8|-1|ad7931-202020|-2|3|ce9642-202020|-3|2|ce9642-202020|-7|-1|cd9a4a-202020|2|2|ce964a-202020|8|-1|b5823a-202020|8|-2|bd8142-202020|11|-5|ce9a4a-202020|11|-13|b5964a-202020|-5|-13|fff76b-202020|0|-16|ffffde-202020|4|-24|fff373-202020" , 0 , 0.9)
		if x ~= - 1 and y ~= - 1 then
			print("找到金色小晶块，位置: " .. x .. ", " .. y)
			按下点击(x , y , - 10 , 10 , - 10 , 10)
			随机延时(200 , 300)
			return true
		end
		return false
	end
	
	-- 物品识别函数：暴走研究所通行证
	local function 检测_暴走研究所通行证(x1 , y1 , x2 , y2)
		local x , y = findMultiColor(x1 , y1 , x2 , y2 , "7b92d6-202020" , "-11|18|73718c-202020|-10|14|94969c-202020|-2|19|8c92a4-202020|0|18|9c9ead-202020|-11|9|529a94-202020|4|-1|315dc5-202020|15|11|5255bd-202020|17|-1|3a415a-202020|-13|0|3161c5-202020|-5|5|e6e7ef-202020|-11|4|adcace-202020|-1|6|d6dbef-202020|-2|10|c5cad6-202020|-4|11|7b7d8c-202020" , 0 , 0.9)
		if x ~= - 1 and y ~= - 1 then
			print("找到暴走研究所通行证，位置: " .. x .. ", " .. y)
			按下点击(x , y , - 10 , 10 , - 10 , 10)
			随机延时(200 , 300)
			return true
		end
		return false
	end
	
	-- 遍历所有格子
	-- 遍历所有格子（自动获取格子数量）
	local 格子数量 = #格子位置
	print("开始遍历仓库格子，共 " .. 格子数量 .. " 个格子")
	
	for i = 1 , 格子数量 do
		-- 直接获取当前格子的坐标
		local 当前格子 = 格子位置[i]
		local x1 = 当前格子[1]
		local y1 = 当前格子[2]
		local x2 = 当前格子[3]
		local y2 = 当前格子[4]
		
		print("检测格子 " .. i .. " 范围: (" .. x1 .. ", " .. y1 .. ") ~ (" .. x2 .. ", " .. y2 .. ")")
		
		-- 在当前格子范围内检测各种物品
		if 检测_金色小金块(x1 , y1 , x2 , y2) then
			print("格子 " .. i .. " 找到金色小晶块并已点击")
			return true
		end
		
		--[===[if 检测_暴走研究所通行证(x1 , y1 , x2 , y2) then
		print("格子 " .. i .. " 找到暴走研究所通行证并已点击")
		return true
		end]===]
		
		-- 延时避免检测过快
		随机延时(50 , 100)
	end
	
	print("遍历完成，未找到目标物品")
	return false
end

